True def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != bg]
    bars = []
    for color in colors:
        top = [c for c in range(w) if g[0][c] == color]
        bottom = [c for c in range(w) if g[h-1][c] == color]
        if top and bottom:
            bars.append((color, 'h', (0, min(top), max(top)), (h-1, min(bottom), max(bottom))))
        left = [r for r in range(h) if g[r][0] == color]
        right = [r for r in range(h) if g[r][w-1] == color]
        if left and right:
            bars.append((color, 'v', (min(left), 0, max(left)), (min(right), w-1, max(right))))
    if not bars:
        return g
    # Corner touches can look like a second, one-cell bar; choose the pair with the longer edge runs.
    line, orient, a, b = max(bars, key=lambda x: ((x[2][2]-x[2][1]+1)+(x[3][2]-x[3][1]+1)) if x[1]=='h' else ((x[2][2]-x[2][0]+1)+(x[3][2]-x[3][0]+1)))
    ray_color = min((v for v in counts if v not in (bg, line)), key=lambda v: counts[v])
    markers = [(r, c) for r in range(h) for c in range(w) if g[r][c] == ray_color]
    if orient == 'h':
        # Dot positions along either bar identify the beam lanes; reuse their
        # offsets on the opposite bar.
        offsets = set()
        for _, lo, hi in (a, b):
            offsets.update(c-lo for r,c in markers if lo <= c <= hi)
        if not offsets:
            offsets = set(range(0, max(a[2]-a[1]+1, b[2]-b[1]+1), 2))
        for row, lo, hi, inward in ((a[0],a[1],a[2],1),(b[0],b[1],b[2],-1)):
            for off in sorted(offsets):
                c = lo + off
                if c > hi: continue
                r = row + inward
                while 0 <= r < h and g[r][c] != line:
                    if g[r][c] == ray_color:
                        g[r][c] = 4
                        break
                    g[r][c] = ray_color
                    r += inward
    else:
        offsets = set()
        for lo, _, hi in (a, b):
            offsets.update(r-lo for r,c in markers if lo <= r <= hi)
        if not offsets:
            offsets = set(range(0, max(a[2]-a[0]+1, b[2]-b[0]+1), 2))
        for col, lo, hi, inward in ((a[1],a[0],a[2],1),(b[1],b[0],b[2],-1)):
            for off in sorted(offsets):
                r0 = lo + off
                if r0 > hi: continue
                c = col + inward
                while 0 <= c < w and g[r0][c] != line:
                    if g[r0][c] == ray_color:
                        g[r0][c] = 4
                        break
                    g[r0][c] = ray_color
                    c += inward
    return g
